  static bool started;string output;bool capture;SurvivalGame g;
  [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void Boot(){var args=RuntimeLaunch.Arguments();bool photo=Array.IndexOf(args,"-growth-capture")>=0;if(started||(!photo&&Array.IndexOf(args,"-growth-smoke")<0))return;started=true;var v=new GameObject("Opt-in growth validation").AddComponent<GrowthValidation>();DontDestroyOnLoad(v.gameObject);v.capture=photo;int n=Array.IndexOf(args,"-validation-output");v.output=n>=0?args[n+1]:Application.persistentDataPath;Directory.CreateDirectory(v.output);if(SurvivalGame.Instance)SurvivalGame.Instance.CombatValidation=true;v.StartCoroutine(v.Run());}
  void Check(bool ok,string why){if(!ok)throw new Exception(why);}
