   Check(growth.Level==1&&growth.Experience==0&&growth.Required==300,"Initial growth state");var victim=g.Enemies[0];victim.Spawn(Floor(g.PlayerPosition+forward*4),0);victim.Health.SetHealth(26);float until=Time.time+2;while(victim.Alive&&Time.time<until)yield return null;Check(!victim.Alive&&growth.Experience==10&&g.ShotsFired==1,"Actual rifle kill did not grant XP");g.EnemyKilled(victim);Check(growth.Experience==10,"Duplicate retirement granted XP");g.config.aimRange=0;
